import numpy as np
from scipy.optimize import least_squares
y=dA_dt
def fit(f,p0,n=30):
    best=None
    for s in range(n):
        rs=np.random.RandomState(s)
        p=np.array(p0,float)*np.exp(rs.randn(len(p0))*0.7)*np.where(rs.rand(len(p0))<0.2,-1,1)
        try:
            r=least_squares(lambda p: f(p)-y, p, max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except: pass
    return best.x, np.mean((f(best.x)-y)**2)/np.var(y)
